-- AYFAR WORLD: online category-based Guess Who with private manual elimination
create table if not exists public.character_game_state(id integer primary key check(id=1),state jsonb not null default '{"stage":"category","category":null,"picks":{"ayoub":null,"farhati":null},"eliminated":{"ayoub":[],"farhati":[]},"turns":{"ayoub":{"questions":0,"attempts":0,"points":0},"farhati":{"questions":0,"attempts":0,"points":0}},"asker":"ayoub","question":null,"answer":null,"finished":false}'::jsonb,updated_at timestamptz not null default now());
insert into public.character_game_state(id) values(1) on conflict(id) do nothing;
alter table public.character_game_state enable row level security;
revoke all on public.character_game_state from anon,authenticated;
create or replace function public.ayfar_character_role() returns text language sql stable security definer set search_path=public as $$ select case when role='farahati' then 'farhati' else role end from public.profiles where id=auth.uid() and role in('ayoub','farhati','farahati') $$;
create or replace function public.character_game_get() returns jsonb language plpgsql security definer set search_path=public as $$ declare s jsonb;p text;begin p:=public.ayfar_character_role();if p is null then raise exception 'غير مصرح';end if;select state into s from public.character_game_state where id=1;if s->>'finished'<>'true' then s:=jsonb_set(s,'{picks}',jsonb_build_object('ayoub',case when p='ayoub' then s#>'{picks,ayoub}' else 'null'::jsonb end,'farhati',case when p='farhati' then s#>'{picks,farhati}' else 'null'::jsonb end));s:=jsonb_set(s,'{eliminated}',jsonb_build_object('ayoub',case when p='ayoub' then s#>'{eliminated,ayoub}' else '[]'::jsonb end,'farhati',case when p='farhati' then s#>'{eliminated,farhati}' else '[]'::jsonb end));end if;return s;end $$;
create or replace function public.character_game_act(action_name text,payload jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare s jsonb;p text;o text;t jsonb;a jsonb;cats text[]:=array['أبطال خارقون','الأنمي والمانغا','أفلام ومسلسلات','شخصيات كرتونية','ألعاب الفيديو','الرياضة وكرة القدم','شخصيات تاريخية','مشاهير وشخصيات معروفة'];
begin p:=public.ayfar_character_role();if p is null then raise exception 'غير مصرح';end if;o:=case when p='ayoub' then 'farhati' else 'ayoub' end;select state into s from public.character_game_state where id=1 for update;
if action_name='reset' then s:='{"stage":"category","category":null,"picks":{"ayoub":null,"farhati":null},"eliminated":{"ayoub":[],"farhati":[]},"turns":{"ayoub":{"questions":0,"attempts":0,"points":0},"farhati":{"questions":0,"attempts":0,"points":0}},"asker":"ayoub","question":null,"answer":null,"finished":false}'::jsonb;
elsif action_name='set_category' then if s#>>'{picks,ayoub}' is not null or s#>>'{picks,farhati}' is not null then raise exception 'لا يمكن تغيير الصنف بعد اختيار شخصية';end if;if not(payload->>'category'=any(cats)) then raise exception 'صنف غير صالح';end if;s:=jsonb_set(s,'{category}',to_jsonb(payload->>'category'));s:=jsonb_set(s,'{stage}','"pick"'::jsonb);
elsif action_name='pick' then if s->>'category' is null or s#>>array['picks',p] is not null then raise exception 'اختَر الصنف أولاً أو سبق أن اخترت';end if;if length(coalesce(payload->>'character',''))<1 then raise exception 'اختيار غير صالح';end if;s:=jsonb_set(s,array['picks',p],to_jsonb(payload->>'character'));if s#>>'{picks,ayoub}' is not null and s#>>'{picks,farhati}' is not null then s:=jsonb_set(s,'{stage}','"ask"'::jsonb);end if;
elsif action_name='question' then if s->>'stage'<>'ask' or s->>'asker'<>p then raise exception 'ليس دورك';end if;if length(trim(coalesce(payload->>'question','')))<2 then raise exception 'اكتب سؤالاً';end if;s:=jsonb_set(s,'{question}',to_jsonb(trim(payload->>'question')));s:=jsonb_set(s,'{answer}','null'::jsonb);s:=jsonb_set(s,'{stage}','"answer"'::jsonb);t:=s#>array['turns',p];s:=jsonb_set(s,array['turns',p,'questions'],to_jsonb(coalesce((t->>'questions')::int,0)+1));
elsif action_name='answer' then if s->>'stage'<>'answer' or s->>'asker'=p then raise exception 'ليس دورك للإجابة';end if;if payload->>'answer' not in('yes','no') then raise exception 'إجابة غير صالحة';end if;s:=jsonb_set(s,'{answer}',to_jsonb(payload->>'answer'));s:=jsonb_set(s,'{stage}','"eliminate"'::jsonb);
elsif action_name in('eliminate','guess') then if s->>'stage'<>'eliminate' or s->>'asker'<>p then raise exception 'ليس دورك';end if;a:=coalesce(payload->'eliminated','[]'::jsonb);if jsonb_typeof(a)<>'array' then raise exception 'قائمة غير صالحة';end if;s:=jsonb_set(s,array['eliminated',p],a);
if action_name='guess' then if payload->>'guess'=s#>>array['picks',o] then t:=s#>array['turns',p];s:=jsonb_set(s,array['turns',p,'points'],to_jsonb(case when coalesce((t->>'questions')::int,0)<=5 then 5 when (t->>'questions')::int<=10 then 3 else 1 end));s:=jsonb_set(s,array['turns',p,'guessed'],'true'::jsonb);s:=jsonb_set(s,'{finished}','true'::jsonb);s:=jsonb_set(s,'{stage}','"result"'::jsonb);else t:=s#>array['turns',p];s:=jsonb_set(s,array['turns',p,'attempts'],to_jsonb(coalesce((t->>'attempts')::int,0)+1));s:=jsonb_set(s,array['asker'],to_jsonb(o));s:=jsonb_set(s,'{stage}','"ask"'::jsonb);end if;
else s:=jsonb_set(s,array['asker'],to_jsonb(o));s:=jsonb_set(s,'{stage}','"ask"'::jsonb);end if;
else raise exception 'إجراء غير معروف';end if;update public.character_game_state set state=s,updated_at=now() where id=1;return public.character_game_get();end $$;
grant execute on function public.character_game_get() to authenticated;grant execute on function public.character_game_act(text,jsonb) to authenticated;